css:
.rk h1 { font-size: 20px; letter-spacing: 1px; margin: 0 0 2px 0; text-transform: uppercase; color: #8d8d8d; }
.rk .rule { border-bottom: 2px solid #1a5fb4; margin: 4px 0 14px 0; }
.rk h2 { font-size: 10px; letter-spacing: 1px; text-transform: uppercase; color: #1a5fb4; margin: 16px 0 6px 0; }
.rk .meta td { padding: 3px 8px 3px 0; vertical-align: top; }
.rk .meta td.k { color: #555; width: 130px; }
.rk .meta td.v { border-bottom: 1px solid #ccc; min-width: 150px; }
.rk table.grid { width: 100%; border-collapse: collapse; margin-top: 4px; }
.rk table.grid th { background: #f2f5f9; text-align: left; font-weight: 600; border-bottom: 1px solid #1a5fb4; padding: 4px 6px; }
.rk table.grid td { border-bottom: 1px solid #e6e6e6; padding: 4px 6px; vertical-align: top; }
.rk .num { text-align: right; white-space: nowrap; }
.rk table.sum { width: 60%; margin-left: 40%; border-collapse: collapse; margin-top: 10px; }
.rk table.sum td { padding: 4px 6px; border-bottom: 1px solid #e6e6e6; }
.rk table.sum tr.total td { border-top: 2px solid #1a5fb4; border-bottom: none; font-weight: 700; font-size: 11px; }
.rk .sign { margin-top: 40px; width: 100%; }
.rk .sign td { width: 45%; padding-top: 26px; border-top: 1px solid #333; font-size: 8px; color: #555; }
.rk .sign td.gap { width: 10%; border: none; }
.rk .muted { color: #777; font-size: 8px; }
.rk .head td { vertical-align: top; }
